#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> powerUpdatesI(std::vector<int>& nums, int p, std::vector<std::vector<int>>& queries) {
        const int MOD = 1e9 + 7;
        std::vector<int> sortedNums = nums;
        std::sort(sortedNums.begin(), sortedNums.end());
        std::vector<int> ans;
        long long curP = p;

        auto power = [&](long long base, long long exp) -> long long {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp & 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return res;
        };

        for (const auto& q : queries) {
            int val = q[0], k = q[1];
            auto it = std::lower_bound(sortedNums.begin(), sortedNums.end(), val);
            sortedNums.insert(it, val);
            int x = sortedNums[sortedNums.size() - k];
            curP = power(curP, x);
            ans.push_back(curP);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] powerUpdatesI(int[] nums, int p, int[][] queries) {
        int MOD = 1_000_000_007;
        List<Integer> list = new ArrayList<>();
        for (int x : nums) list.add(x);
        Collections.sort(list);
        int[] ans = new int[queries.length];
        long curP = p;

        for (int i = 0; i < queries.length; i++) {
            int val = queries[i][0], k = queries[i][1];
            int idx = Collections.binarySearch(list, val);
            if (idx < 0) idx = -idx - 1;
            list.add(idx, val);
            int x = list.get(list.size() - k);
            curP = power(curP, x, MOD);
            ans[i] = (int)curP;
        }
        return ans;
    }

    private long power(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

function powerUpdatesI(nums, p, queries) {
    const MOD = 1000000007n;
    const sorted = [...nums].sort((a, b) => a - b);
    const ans = [];
    let curP = BigInt(p);

    function power(base, exp) {
        let res = 1n;
        base = base % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    function insort(arr, target) {
        let low = 0, high = arr.length;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (arr[mid] < target) low = mid + 1;
            else high = mid;
        }
        arr.splice(low, 0, target);
    }

    for (const [val, k] of queries) {
        insort(sorted, val);
        const x = sorted[sorted.length - k];
        curP = power(curP, x);
        ans.push(Number(curP));
    }
    return ans;
}
